quat=np.array([0.,1.,0.,0.]); current=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10]); callnum=0

def saveobs(name='view',cams=None,depth=False):
 o=r.get_obs(cameras=cams,depth=depth)
 for c,a in o.last.items(): Image.fromarray(a).save(root/f'{name}_{c}.png')
 for c,a in o.last_depth.items(): np.save(root/f'{name}_{c}_depth.npy',a)
 (root/f'{name}_meta.json').write_text(json.dumps(o.meta,indent=2))
 return o

def submit(rows,cams=[]):
 global current,callnum
 rows=np.asarray(rows)
 for start in range(0,len(rows),180):
  part=rows[start:start+180]
  before=r.status()
  np.save(root/f'actions_{callnum:05d}.npy',part)
  try: res=r.submit('ee_pose',part,dt=.05,cameras=cams,video='none')
  except Exception:
   s=r.wait_ready(); print('RECOVER',s,flush=True)
   if s['control_steps']==before['control_steps']: res=r.submit('ee_pose',part,dt=.05,cameras=cams,video='none')
   else: res=r.get_obs(cameras=[])
  current=np.array(res.meta['proprio']['now'][7:10]); callnum+=1
  (root/'latest_meta.json').write_text(json.dumps(res.meta))
  if res.meta.get('plan'): 
