def path(points,speed=.07,hold=.15):
 global current
 p0=current.copy(); rows=[]
 for p in points:
  p=np.array(p,dtype=float); n=max(1,int(np.ceil(np.linalg.norm(p-p0)/(speed*.05))))
  for a in np.linspace(0,1,n+1)[1:]: rows.append([*(p0+(p-p0)*a),*quat])
  p0=p
 rows.extend([[*p0,*quat]]*int(hold/.05))
 return submit(rows)

